create function linklemon_private.push_available() returns boolean language sql security definer set search_path='' as $$ select auth.uid() is not null and linklemon_private.beta_allowed() and exists(select 1 from linklemon_private.push_dispatch_config where enabled) $$; revoke all on function linklemon_private.push_available() from public,anon,authenticated; grant execute on function linklemon_private.push_available() to authenticated; create function public.push_available() returns boolean language sql security invoker set search_path='' as $$select linklemon_private.push_available()$$; revoke all on function public.push_available() from public,anon,authenticated; grant execute on function public.push_available() to authenticated;
